import { mkdir, readFile, writeFile } from 'node:fs/promises'
import { dirname, relative } from 'node:path'
import type { FileWrite, StepState } from '../step'

export const GENERATED_HEADER = [
  '// Generated by @beastjs/auth. Do not edit it by hand: re-run `bunx @beastjs/auth`',
  '// and your changes here will be replaced.'
].join('\n')

/** Prefixes a generated module with the house header, which every emitted file carries. */
export const withHeader = (body: string) => `${GENERATED_HEADER}\n\n${body.trimStart()}`

export type WriteOutcome = 'created' | 'replaced' | 'unchanged'

async function readIfPresent(path: string): Promise<string | null> {
  try {
    return await readFile(path, 'utf8')
  } catch {
    return null
  }
}

/**
 * Writes a generated file, reporting whether it changed anything.
 *
 * An unchanged file is not rewritten: the `--check` mode and a re-run both lean
 * on byte equality, and touching a file that is already correct would make a
 * clean re-run look like work.
 */
export async function emitFile(write: FileWrite): Promise<WriteOutcome> {
  const existing = await readIfPresent(write.path)
  if (existing === write.contents) return 'unchanged'

  await mkdir(dirname(write.path), { recursive: true })
  await writeFile(write.path, write.contents, 'utf8')

  return existing === null ? 'created' : 'replaced'
}

export async function emitAll(writes: readonly FileWrite[]): Promise<Map<string, WriteOutcome>> {
  const outcomes = new Map<string, WriteOutcome>()
  for (const write of writes) {
    outcomes.set(write.path, await emitFile(write))
  }
  return outcomes
}

/**
 * How a set of intended writes compares with what is on disk — the basis of both
 * `--check` and the skip-vs-run decision on a re-run.
 *
 * `partial` means some files match and some do not, which is what an interrupted
 * run leaves behind. It is reported rather than resolved, because overwriting a
 * file the user has since edited is not this function's call to make.
 */
export async function detectWrites(writes: readonly FileWrite[]): Promise<StepState> {
  if (writes.length === 0) return 'satisfied'

  let matching = 0
  let present = 0

  for (const write of writes) {
    const existing = await readIfPresent(write.path)
    if (existing !== null) present += 1
    if (existing === write.contents) matching += 1
  }

  if (matching === writes.length) return 'satisfied'
  if (present === 0) return 'absent'
  return 'partial'
}

/** Paths shown to the user are relative to the app, never absolute — they are what they'd type. */
export const toDisplayPath = (root: string, path: string) => relative(root, path) || path
